internal const val VIETNAMESE_ASCII: Int = 27
internal const val VIETNAMESE_NON_ASCII: Int = 25
internal const val CENTRAL_ASCII: Int = 27
internal const val CENTRAL_NON_ASCII: Int = 41
internal const val CYRILLIC_ASCII: Int = 2
internal const val CYRILLIC_NON_ASCII: Int = 44
internal const val WESTERN_ASCII: Int = 27
internal const val WESTERN_NON_ASCII: Int = 32
internal const val ICELANDIC_ASCII: Int = 27
internal const val ICELANDIC_NON_ASCII: Int = 13
internal const val GREEK_ASCII: Int = 2
internal const val GREEK_NON_ASCII: Int = 35
internal const val TURKISH_ASCII: Int = 26
internal const val TURKISH_NON_ASCII: Int = 13
internal const val HEBREW_ASCII: Int = 2
internal const val HEBREW_NON_ASCII: Int = 34
internal const val ARABIC_ASCII: Int = 2
internal const val ARABIC_NON_ASCII: Int = 51
internal const val BALTIC_ASCII: Int = 27
internal const val BALTIC_NON_ASCII: Int = 19
internal const val THAI_ASCII: Int = 2
internal const val THAI_NON_ASCII: Int = 70

internal fun computeIndex(
    x: Int,
    y: Int,
    asciiClasses: Int,
    nonAsciiClasses: Int,
): Int? {
    if (x == 0 && y == 0) {
        return null
    }
    if (x < asciiClasses && y < asciiClasses) {
        return null
    }
    if (y >= asciiClasses) {
        return (asciiClasses * nonAsciiClasses) +
            (asciiClasses + nonAsciiClasses) * (y - asciiClasses) +
            x
    }
    return y * nonAsciiClasses + x - asciiClasses
}

public class SingleByteData(
    public val encoding: Encoding,
    internal val lower: ByteArray,
    internal val upper: ByteArray,
    internal val probabilities: ByteArray,
    internal val ascii: Int,
    internal val nonAscii: Int,
) {
    public fun classify(byte: Byte): Int {
        val b = byte.toInt() and 0xFF
        val high = b ushr 7
        val low = b and 0x7F
        return if (high == 0) {
            lower[low].toInt() and 0xFF
        } else {
            upper[low].toInt() and 0xFF
        }
    }

    public fun isLatinAlphabetic(caselessClass: Int): Boolean = caselessClass > 0 && caselessClass < (ascii + nonAscii)

    public fun isNonLatinAlphabetic(caselessClass: Int, isWindows1256: Boolean): Boolean {
        val lowerBound = if (isWindows1256) WINDOWS_1256_ZWNJ else 1
        return caselessClass > lowerBound && caselessClass < (ascii + nonAscii)
    }

    public fun score(
        currentClass: Int,
        previousClass: Int,
        isWindows1256: Boolean,
    ): Long {
        val currentUsize = currentClass
        val previousUsize = previousClass
        val storedBoundary = ascii + nonAscii
        if (currentUsize < storedBoundary) {
            if (previousUsize < storedBoundary) {
                val index = computeIndex(previousUsize, currentUsize, ascii, nonAscii)
                return if (index != null) {
                    val b = probabilities[index].toInt() and 0xFF
                    if (b == 255) {
                        IMPLAUSIBILITY_PENALTY
                    } else {
                        b.toLong()
                    }
                } else {
                    0L
                }
            } else {
                if (currentUsize == 0 ||
                    currentUsize == ASCII_DIGIT ||
                    (isWindows1256 && currentUsize == WINDOWS_1256_ZWNJ)
                ) {
                    return 0L
                } else {
                    val previousUnstored = previousUsize - storedBoundary
                    return when (previousUnstored) {
                        PLAUSIBLE_NEXT_TO_ALPHABETIC_ON_EITHER_SIDE -> 0L
                        IMPLAUSIBLE_NEXT_TO_ALPHABETIC_ON_EITHER_SIDE -> IMPLAUSIBILITY_PENALTY
                        IMPLAUSIBLE_BEFORE_ALPHABETIC -> IMPLAUSIBILITY_PENALTY
                        IMPLAUSIBLE_AFTER_ALPHABETIC -> 0L
                        PLAUSIBLE_NEXT_TO_NON_ASCII_ALPHABETIC_ON_EITHER_SIDE -> {
                            if (currentUsize < ascii) {
                                IMPLAUSIBILITY_PENALTY
                            } else {
                                0L
                            }
                        }
                        PLAUSIBLE_NEXT_TO_ASCII_ALPHABETIC_ON_EITHER_SIDE -> {
                            if (currentUsize < ascii) {
                                0L
                            } else {
                                IMPLAUSIBILITY_PENALTY
                            }
                        }
                        else -> 0L
                    }
                }
            }
        } else {
            if (previousUsize < storedBoundary) {
                if (previousUsize == 0 ||
                    previousUsize == ASCII_DIGIT ||
                    (isWindows1256 && previousUsize == WINDOWS_1256_ZWNJ)
                ) {
                    return 0L
                } else {
                    val currentUnstored = currentUsize - storedBoundary
                    return when (currentUnstored) {
                        PLAUSIBLE_NEXT_TO_ALPHABETIC_ON_EITHER_SIDE -> 0L
                        IMPLAUSIBLE_NEXT_TO_ALPHABETIC_ON_EITHER_SIDE -> IMPLAUSIBILITY_PENALTY
                        IMPLAUSIBLE_BEFORE_ALPHABETIC -> 0L
                        IMPLAUSIBLE_AFTER_ALPHABETIC -> IMPLAUSIBILITY_PENALTY
                        PLAUSIBLE_NEXT_TO_NON_ASCII_ALPHABETIC_ON_EITHER_SIDE -> {
                            if (previousUsize < ascii) {
                                IMPLAUSIBILITY_PENALTY
                            } else {
                                0L
                            }
                        }
                        PLAUSIBLE_NEXT_TO_ASCII_ALPHABETIC_ON_EITHER_SIDE -> {
                            if (previousUsize < ascii) {
                                0L
                            } else {
                                IMPLAUSIBILITY_PENALTY
                            }
                        }
                        else -> 0L
                    }
                }
            } else if (currentUsize == ASCII_DIGIT || previousUsize == ASCII_DIGIT) {
                return 0L
            } else {
                return IMPLAUSIBILITY_PENALTY
            }
        }
    }

    override fun equals(other: Any?): Boolean = this === other

    override fun hashCode(): Int = super.hashCode()
}

